import { EventData } from '@esotericsoftware/spine-pixi-v8';
import { SoundInstance } from './sound-instance';

export type ExtendedAudioContextState = AudioContextState | 'interrupted';

export interface PlayOptions {
    delay: number;
    speed?: number;
    loop?: boolean;
    volume?: number;
    sprite?: string;
    muted?: boolean;
    singleInstance?: boolean;
}

export type AudioInput = string | { name: string; sprite?: string };

export interface ISoundManagerEvents {
    isUnlocked(value: boolean): void;
}

export interface IMusicSpineSoundData {
    category: string;
    name: string;
    soundInstances: SoundInstance[];
}

export interface ISoundStartingInfo {
    soundInstance?: SoundInstance;
    data: EventData;
    elapsedTime: number;
}

export interface IAudioPath {
    category: string;
    sound: string
}

export interface ICrossFadeResponse {
    to: SoundInstance,
    from: SoundInstance,
    timeline: gsap.core.Timeline;
}

export interface IAudioEventData {
    audioPath: string | undefined;
    balance: number;
    floatValue: number;
    intValue: number;
    name: string;
    stringValue: string;
    volume: number;
}

export interface IMusicSpineAction {
    name: string;
    args: string[];
}

export interface ISoundManagerOptions {
    disableAutoPause: boolean;
    disablePlaybackBeforeUnlock: boolean;
    stopSoundsOnVisibilityChange: boolean;
}

export interface IDynamicSoundOptions {
    randomPlayOrder: boolean;
    volume: number;
}

export interface ICrossfadeOptions {
    duration: number;
    playOptions: Omit<ISoundPlayOptions, 'sprite' | 'delayInMs'>;
}

export interface IFadeOptions {
    duration: number;
    toVolume: number;
}

export interface ITrack {
    name: string;
    soundId: number;
    options: ISoundPlayOptions;
}

export interface ISoundPlayOptions {
    sprite?: string;
    delayInMs?: number;
    loop?: boolean;
    volume?: number;
    rate?: number;
    /** @deprecated Use `seek` instead */
    start?: number;
    seek?: number;
    muted?: boolean;
}

export interface ISoundInstanceOptions extends ISoundPlayCategoryOptions {
    categoryVolume: number;
    categoryMute: boolean;
}

export interface ISoundPlayCategoryOptions extends ISoundPlayOptions {
    category: string;
}